                        break :blk (if ((actual_el[@as(usize, @intCast((actual_el.len - 1)))] == 44)) actual[@as(usize, @intCast((u(x) - 1)))] else expected[@as(usize, @intCast((u(y) - 1)))]);
                    } else {
                        break :blk actual[@as(usize, @intCast((u(x) - 1)))];
                    }
};
                    _ = result.appendAssumeCapacity(.{ .kind = .equal, .value = line });
                    x = (x - 1);
                    y = (y - 1);
                }
                if ((diff_level > 0)) {
                    if ((x > prev_x)) {
                        _ = try result.append(.{ .kind = .insert, .value = actual[@as(usize, @intCast((u(x) - 1)))] });
                        x = (x - 1);
                    } else {
                        _ = try result.append(.{ .kind = .delete, .value = expected[@as(usize, @intCast((u(y) - 1)))] });
                        y = (y - 1);
                    }
                }
            }
            return result;
    }

pub inline fn u(n: anytype) uint {
            return @intCast(n);
    }

pub inline fn us(n: anytype) usize {
