    }

pub inline fn i(n: anytype) int {
            return @intCast(n);
    }
    pub const eql = areLinesEql;
    pub const LineType = Line;
};
}

pub fn printDiff(comptime T: type, diffs: std.array_list.Managed(Diff(T))) !void {
        const stdout = (if (builtin.is_test) std.fs.File.stderr().writer() else std.fs.File.stdout().writer());
        {
            var idx: i32 = 0;
            _ = &idx;
            const __end_0 = diffs.items.len;
            while (idx < __end_0) : (idx += 1) {
                const d = diffs.items[@as(usize, @intCast((diffs.items.len - (idx + 1))))];
                const op: u8 = (switch (d.kind) {
inline .equal => (if (comptime @typeInfo(@TypeOf(32)) == .@"enum") cp_cast_int(u8, @intFromEnum(32)) else cp_cast_int(u8, 32)),
inline .insert => (if (comptime @typeInfo(@TypeOf(43)) == .@"enum") cp_cast_int(u8, @intFromEnum(43)) else cp_cast_int(u8, 43)),
inline .delete => (if (comptime @typeInfo(@TypeOf(45)) == .@"enum") cp_cast_int(u8, @intFromEnum(45)) else cp_cast_int(u8, 45)),
});
                _ = try stdout.writeByte(op);
                _ = try stdout.print(" {any}\n", .{ (if (@typeInfo(@TypeOf(d)) == .@"enum") @intFromEnum(d) else d.value) });
            }
        }
}

pub fn areCharsEqual(comptime T: type, a: T, b: T) bool {
        return (a == b);
}

pub fn areLinesEqual(comptime T: type, a: T, b: T, comptime check_comma_disparity: bool) bool {
        if (((T == u8) or (T == u32))) {
            return (a == b);
        }
        if (((((T == StringConst) or (T == StringMut)) or (T == StringZConst)) or (T == StringZMut))) {
            return areStrLinesEqual(T, a, b, check_comma_disparity);
        }
        _ = @compileError("areLinesEqual can only compare chars and strings.");
}

pub fn areStrLinesEqual(comptime T: type, a: T, b: T, comptime check_comma_disparity: bool) bool {
        const info = @typeInfo(T);
        const ChildType = info.pointer.child;
        if (comptime (!check_comma_disparity)) {
            return mem.eql(ChildType, a, b);
        }
        const largest = (if ((a.len > b.len)) a else b);
        const smallest = (if ((a.len > b.len)) b else a);
        return (switch ((largest.len - smallest.len)) {
inline 0 => mem.eql(ChildType, a, b),
inline 1 => ((largest[@as(usize, @intCast((largest.len - 1)))] == 44) and mem.eql(ChildType, largest[0..smallest.len], smallest)),
else => false,
});
}

pub fn LineCmp(comptime Line: type) type {
        return *const fn(a: Line, b: Line) bool;
}

pub fn Diff(comptime T: type) type {
        return struct {
    kind: DiffKind,
    value: T,

pub fn eql(self: @This(), other: Self) bool {
            return ((self.kind == other.kind) and mem.eql(T, self.value, (if (@typeInfo(@TypeOf(other)) == .@"enum") @intFromEnum(other) else other.value)));
    }

pub fn format(value: anytype, writer: *std.Io.Writer) !void {
            return writer.print("{} {any}", .{ value.kind, (if (@typeInfo(@TypeOf(value)) == .@"enum") @intFromEnum(value) else value.value) });
    }
    const Self = @This();
};
}

pub fn DiffList(comptime T: type) type {
        return std.array_list.Managed(Diff(T));
}

pub fn SplitList(comptime T: type) type {
        return std.ArrayListUnmanaged((if ((T == u8)) StringConst else String16Const));
}

pub fn split(comptime T: type, alloc: Allocator, s: []const T) Allocator.Error!SplitList(T) {
        comptime {
        if (((T != u8) and (T != u16))) {
            _ = @compileError("Split only supports latin1, utf8, and utf16.");
        }

}
        const newline: T = (if (comptime @typeInfo(T) == .@"enum") @as(T, @enumFromInt(10)) else @as(T, 10));
        var it = std.mem.splitScalar(T, s, newline);
        _ = &it;
        var lines: SplitList(T) = .{};
        _ = &lines;
        _ = try lines.ensureUnusedCapacity(alloc, cp_shr(s.len, 4));
        errdefer {
        _ = lines.deinit(alloc);
        }
        while (it.next()) |l| {
            _ = try lines.append(alloc, l);
        }
        return lines;
}
